Investment:[{title:'Customer',fields:[...customerFields,F('planFor','Plan is for','select',true,['Self','Child']),F('goal','Goal','select',true,['Child education','Child marriage','Retirement','Regular income','Savings / wealth','Other'])]},{title:'Plan',fields:[F('insuredName','Insured name','text',true),F('dob','Insured date of birth','date',true),F('budget','Premium budget (₹)','number',true),F('paymentFrequency','Payment frequency','select',true,['Monthly','Quarterly','Half yearly','Yearly','Single premium']),F('paymentTerm','Payment term (years)','number'),F('policyTerm','Policy term (years)','number'),F('notes','Notes','textarea')]}],
'Group Health':[{title:'What kind of GHI case is this?',fields:[...caseFields,F('filledFormat','Filled Group Health format','file')]},{title:'Company details',fields:companyFields},{title:'Coverage requirements',fields:[F('employees','Employee count','number',true),F('dependants','Dependants covered','select',true,['Employees only','Employee + spouse + children','Employee + parents','Employee + family + parents']),F('sumInsured','Sum insured per family (₹)','number',true),F('maternity','Maternity required','select',false,['No','Yes']),F('pedCover','Pre-existing disease cover','select',false,['From day one','Standard waiting period'])]},{title:'Upload employee data',fields:[F('employeeData','Employee data (Excel / CSV)','file',true),...priorFields]},{title:'Anything else?',fields:[F('notes','Additional requirements','textarea')]}],
