'Jewellery Block':[{title:'Business information',fields:[F('company','Business / shop name','text',true),...customerFields,F('address','Shop address','textarea',true),F('policyPeriod','Required policy period'),F('businessMix','Retail / wholesale percentages'),F('claimHistory','Claims in the last 5 years','textarea',true)]},{title:'Security arrangements',fields:[F('security','Security measures','checks',true,['Guard / watchman','CCTV','Burglar alarm','Strong room / vault','Rolling shutters','Fire extinguisher','24-hour guard','Hydrant / sprinkler']),F('safe','Safe brand and model','text',true)]},{title:'Coverage amounts',fields:[F('stockValue','Stock in shop / safe / counter (₹)','number',true),F('outsideSafe','Stock outside safe overnight (%)','number',true),F('counterValue','Overnight counter stock (₹)','number'),F('staffStock','Stock with partners / staff (₹)','number'),F('workerStock','Stock with workers / brokers (₹)','number'),F('workerYears','Years with workers / brokers'),F('transitValue','Transit cover per trip (₹)','number'),F('furnitureValue','Furniture / fixtures (₹)','number'),F('cashValue','Cash in safe / transit (₹)','number'),F('notes','Other required cover','textarea')]}]
