const leadStages=['New','Quote given','Booked','Policy issued','Won & Mapped','Lost'];
function normalisePhone(v){let n=String(v||'').replace(/\D/g,'');return n.length===12&&n.startsWith('91')?n.slice(2):n}
function validPhone(v){return /^[6-9]\d{9}$/.test(normalisePhone(v))}
function dateISO(value=new Date()){let d=new Date(value);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function amount(v){let n=Number(v);return Number.isFinite(n)?n:0}
function safeLoad(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
const workspace=safeLoad('sigma-workspace-v2',{profile:{name:'Partner',phone:'',email:'',agentCode:'',publicWebsite:'',referralLink:''},quotes:[],payouts:[],rates:[],assets:[],prospects:[],services:{},pinned:[]});
for(const key of ['quotes','payouts','rates','assets','prospects','pinned'])if(!Array.isArray(workspace[key]))workspace[key]=[];
workspace.profile||={name:'Partner'};workspace.services||={};
function saveWorkspace(){localStorage.setItem('sigma-workspace-v2',JSON.stringify(workspace))}
function uid(prefix='S'){return prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2))}
function activityLog(text){db.activity.unshift({text,date:new Date().toLocaleString('en-IN')});save()}
function optionsHTML(options,value,empty=true){return (empty?'<option value="">Select…</option>':'')+options.map(v=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${/^\d{6,}$/.test(v)?rupee(v):esc(v)}</option>`).join('')}
function fieldHTML(f,value='',onchange=''){const attrs=`id="${f.key}" name="${f.key}" ${f.required?'required':''} ${onchange?`onchange="${onchange}"`:''}`;let control;if(f.type==='select')control=`<select ${attrs}>${optionsHTML(f.options,value)}</select>`;else if(f.type==='textarea')control=`<textarea ${attrs} rows="3">${esc(value)}</textarea>`;else if(f.type==='checks')control=`<div class="check-options">${f.options.map(v=>`<label><input type="checkbox" name="${f.key}" value="${esc(v)}" ${(Array.isArray(value)?value:[]).includes(v)?'checked':''}>${esc(v)}</label>`).join('')}</div>`;else if(f.type==='file')control=`<input type="file" name="${f.key}" accept="image/*,application/pdf,.csv,.xlsx,.xls" onchange="stageFile('${f.key}',this)"><span class="subtle" id="file-${f.key}">${esc(value?.name||'PDF, photo, Excel or CSV · up to 10 MB')}</span>`;else if(f.type==='members')control=`<div id="members-${f.key}">${memberInputs(f.key,Array.isArray(value)&&value.length?value:[{relation:'Self',name:'',age:''}])}</div><button type="button" onclick="addInsuredMember('${f.key}')">${I('plus')} Add family member</button>`;else control=`<input type="${f.type}" ${attrs} value="${esc(value)}" ${f.type==='number'?'min="0" step="any"':f.type==='tel'?'inputmode="tel" pattern="(?:\\+?91 ?)?[6-9][0-9]{9}"':f.key==='pan'?'pattern="[A-Za-z]{5}[0-9]{4}[A-Za-z]" maxlength="10"':''}>`;return `<div class="field ${['textarea','checks','file','members'].includes(f.type)?'full':''}"><label for="${f.key}">${esc(f.label)} ${f.required?'<span class="required">*</span>':''}</label>${control}</div>`}
function memberInputs(key,members){return members.map((m,i)=>`<div class="insured-row" data-member="${key}"><select aria-label="Member ${i+1} relation" name="${key}-relation">${optionsHTML(['Self','Spouse','Son','Daughter','Mother','Father','Father-in-law','Mother-in-law','Other'],m.relation,false)}</select><input name="${key}-name" aria-label="Member ${i+1} name" placeholder="Member name" value="${esc(m.name)}"><input name="${key}-age" aria-label="Member ${i+1} age" type="number" placeholder="Age" min="0" max="120" value="${esc(m.age)}" required><button type="button" class="quiet" aria-label="Remove member ${i+1}" onclick="this.closest('.insured-row').remove()">${I('close')}</button></div>`).join('')}
function addInsuredMember(key){document.querySelector('#members-'+key).insertAdjacentHTML('beforeend',memberInputs(key,[{relation:'Spouse',name:'',age:''}]))}
let attachmentDB;
function filesDB(){return attachmentDB||(attachmentDB=new Promise((resolve,reject)=>{let r=indexedDB.open('sigma0nine-documents',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}))}
async function persistFile(file,allowVideo=false){if(!file)return null;if(file.size>10*1024*1024)throw Error('Each file must be 10 MB or smaller');if(!(allowVideo&&['video/mp4','video/webm'].includes(file.type))&&!/^(image\/|application\/pdf$)/.test(file.type)&&!(/\.(csv|xlsx|xls)$/i.test(file.name)))throw Error('Choose a photo, PDF or spreadsheet');let storeDB=await filesDB(),id=uid('FILE');await new Promise((resolve,reject)=>{let t=storeDB.transaction('files','readwrite');t.objectStore('files').put({id,file});t.oncomplete=resolve;t.onerror=()=>reject(t.error)});return {id,name:file.name,type:file.type,size:file.size}}
async function readAttachment(id){let storeDB=await filesDB();return new Promise((resolve,reject)=>{let r=storeDB.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result?.file);r.onerror=()=>reject(r.error)})}
async function downloadAttachment(id){try{let f=await readAttachment(id);if(!f)throw Error('This document is not in this browser');fileDownload(f.name,f,f.type)}catch(e){toast(e.message)}}
let wizard=safeLoad('sigma-lead-draft',null),pendingFiles={};
function startLead(product='Health',contactId=''){product=product==='Life'?'Investment':product;const c=db.contacts.find(c=>c.id===contactId);wizard={product,step:0,data:c?{name:c.name,phone:c.phone,email:c.email}: {},updated:dateISO()};pendingFiles={};saveWizard();closeModal();go('leadform')}
function saveWizard(){localStorage.setItem('sigma-lead-draft',JSON.stringify(wizard))}
function wizardSteps(){return (WORKFLOWS[wizard?.product]||WORKFLOWS.Health).filter(s=>!s.when||s.when(wizard.data))}
function leadFormPage(){if(!wizard)return heading('CREATE LEAD','Choose a product','Start from the product catalogue.',btn('View products',"go('sell')",'grid',true));const steps=wizardSteps();wizard.step=Math.min(wizard.step,steps.length);const reviewing=wizard.step===steps.length,step=steps[wizard.step];return heading('REFER & EARN',wizard.product+' lead','Your draft is automatically saved in this browser.',btn('Back to products',"go('sell')",'grid'))+`<div class="flow-layout"><aside class="flow-steps">${[...steps,{title:'Review & submit'}].map((s,i)=>`<div class="flow-step ${i===wizard.step?'current':''}"><span>${i<wizard.step?I('check'):i+1}</span>${esc(s.title)}</div>`).join('')}<p class="subtle">Documents stay in this browser. AI extraction and team approval need a connected service.</p></aside><section class="card pad"><h2>${reviewing?'Review your lead':esc(step.title)}</h2>${reviewing?leadReview():`<form id="leadWizard" oninput="rememberWizard(this)" onchange="rememberWizard(this)" onsubmit="event.preventDefault();advanceWizard(this)"><div class="formgrid">${step.fields.map(f=>fieldHTML(f,wizard.data[f.key]??'')).join('')}</div><div class="modalfoot">${wizard.step?'<button type="button" onclick="wizardBack()">Back</button>':''}<button class="primary" type="submit">Review / Continue</button></div></form>`}</section></div>`}
async function stageFile(key,input){if(input.files[0]){if(input.files[0].size>10*1024*1024){input.value='';toast('Maximum file size is 10 MB');return}pendingFiles[key]=input.files[0];document.querySelector('#file-'+key).textContent=input.files[0].name}}
async function collectWizard(form){const step=wizardSteps()[wizard.step],values=new FormData(form);for(const f of step.fields){if(f.type==='file'){if(pendingFiles[f.key]){wizard.data[f.key]=await persistFile(pendingFiles[f.key]);delete pendingFiles[f.key]}if(f.required&&!wizard.data[f.key])throw Error('Please attach '+f.label)}else if(f.type==='checks')wizard.data[f.key]=values.getAll(f.key);else if(f.type==='members'){let names=values.getAll(f.key+'-name'),ages=values.getAll(f.key+'-age'),relations=values.getAll(f.key+'-relation');if(!relations.length)throw Error('Add at least one insured member');wizard.data[f.key]=relations.map((relation,i)=>({relation,name:names[i],age:ages[i]}))}else wizard.data[f.key]=values.get(f.key)||''}if(wizard.data.phone&&!validPhone(wizard.data.phone))throw Error('Enter a valid 10-digit Indian mobile');if(wizard.data.departure&&wizard.data.returnDate&&wizard.data.returnDate<wizard.data.departure)throw Error('Return date must follow departure');saveWizard()}
async function advanceWizard(form){try{await collectWizard(form);wizard.step++;saveWizard();render();window.scrollTo(0,0)}catch(e){toast(e.message)}}
function wizardBack(){wizard.step=Math.max(0,wizard.step-1);saveWizard();render()}
function reviewValue(value){if(Array.isArray(value))return value.map(v=>typeof v==='object'?`${esc(v.relation)} · ${esc(v.name||'Member')} · ${esc(v.age)} years`:esc(v)).join('<br>');if(value&&typeof value==='object'&&value.id)return `<button class="linkbutton" onclick="downloadAttachment('${value.id}')">${I('download')}${esc(value.name)}</button>`;return esc(value)}
function leadReview(){return `<dl class="review-list">${Object.entries(wizard.data).filter(([,v])=>v!==''&&v!=null).map(([k,v])=>`<div><dt>${esc((WORKFLOWS[wizard.product]||[]).flatMap(s=>s.fields).find(f=>f.key===k)?.label||k)}</dt><dd>${reviewValue(v)}</dd></div>`).join('')}</dl><div class="notice">Saving creates a local lead. It does not send it to Incremint, an insurer or a relationship manager.</div><div class="modalfoot">${btn('Back','wizardBack()')}${btn('Save lead',"saveProductLead()",'check',true)}</div>`}
function saveProductLead(){const d=wizard.data;if(!d.name||!validPhone(d.phone))return toast('Customer name and valid mobile are required');let lead={...d,id:uid('LEAD'),name:d.name.trim(),phone:normalisePhone(d.phone),product:wizard.product,premium:amount(d.budget||d.previousPremium),status:'New',date:dateISO(),createdAt:new Date().toISOString(),details:structuredClone(d)};db.leads.unshift(lead);if(!db.contacts.some(c=>normalisePhone(c.phone)===lead.phone))db.contacts.unshift({id:uid('CONTACT'),name:lead.name,phone:lead.phone,email:d.email||'',type:'Lead',active:true,createdAt:new Date().toISOString()});activityLog('Lead saved: '+lead.name);wizard=null;localStorage.removeItem('sigma-lead-draft');go('leads');toast('Lead saved in your workspace')}

function rememberWizard(form){if(!wizard)return;let step=wizardSteps()[wizard.step];if(!step)return;let data=new FormData(form);for(let f of step.fields){if(f.type==='file')continue;if(f.type==='checks')wizard.data[f.key]=data.getAll(f.key);else if(f.type==='members'){let names=data.getAll(f.key+'-name'),ages=data.getAll(f.key+'-age'),relations=data.getAll(f.key+'-relation');wizard.data[f.key]=relations.map((relation,i)=>({relation,name:names[i],age:ages[i]}))}else wizard.data[f.key]=data.get(f.key)||''}saveWizard()}
